code_examples.bad:
try {
    riskyOperation();
} catch (Exception e) {
    // Do nothing - exception swallowed
}

code_examples.good:
try {
    riskyOperation();
} catch (Exception e) {
    logger.error("Failed to perform risky operation", e);
    throw new ServiceException("Operation failed", e);
}

code_examples.bad:
try {
    databaseOperation();
} catch (Exception e) {
    return defaultValue; // Catches everything, even RuntimeException
}

code_examples.good:
try {
    databaseOperation();
} catch (SQLException e) {
    logger.error("Database error", e);
    throw new DataAccessException("Failed to access database", e);
} catch (TimeoutException e) {
    logger.warn("Database timeout", e);
    return cachedValue;
}

code_examples.bad:
public void processOrder(Order order) {
    try {
        paymentService.charge(order);
    } catch (PaymentException e) {
        logger.error("Payment failed", e);
        // Method returns normally despite failure
    }
}

code_examples.good:
public void processOrder(Order order) throws OrderProcessingException {
    try {
        paymentService.charge(order);
    } catch (PaymentException e) {
        logger.error("Payment failed for order {}", order.getId(), e);
        throw new OrderProcessingException("Failed to process order", e);
    }
}

code_examples.bad:
HttpClient client = HttpClient.newHttpClient();
HttpResponse<String> response = client.send(request, BodyHandlers.ofString());
// No timeout - can hang indefinitely

Connection conn = dataSource.getConnection();
Statement stmt = conn.createStatement();
ResultSet rs = stmt.executeQuery(sql);
// No try-with-resources, connections not closed on exception

code_examples.good:
try (Connection conn = dataSource.getConnection();
     Statement stmt = conn.createStatement();
     ResultSet rs = stmt.executeQuery(sql)) {
    // Process results
} // Automatically closed even on exception

code_examples.bad:
private static final Map<String, Object> cache = new HashMap<>();

public Object get(String key) {
    return cache.computeIfAbsent(key, this::loadFromDatabase);
    // Cache grows unbounded, never evicts entries
}

code_examples.good:
private static final Cache<String, Object> cache = CacheBuilder.newBuilder()
    .maximumSize(10000)
    .expireAfterWrite(1, TimeUnit.HOURS)
    .build();

public Object get(String key) {
    return cache.get(key, this::loadFromDatabase);
}

code_examples.bad:
FileInputStream fis = new FileInputStream(file);
byte[] data = fis.readAllBytes();
// Stream not closed

code_examples.good:
try (FileInputStream fis = new FileInputStream(file)) {
    byte[] data = fis.readAllBytes();
} // Automatically closed

code_examples.bad:
List<Order> orders = orderRepository.findAll();
for (Order order : orders) {
    Customer customer = customerRepository.findById(order.getCustomerId());
    // N+1 queries: 1 for orders + N for customers
}

code_examples.good:
Page<Order> orders = orderRepository.findAll(
    PageRequest.of(page, size, Sort.by("createdAt").descending())
);

code_examples.bad:
@Transactional
public void processOrder(Order order) {
    validateOrder(order); // External API call in transaction
    sendEmail(order); // Email sending in transaction
    updateDatabase(order);
}

code_examples.good:
public void processOrder(Order order) {
    validateOrder(order); // Outside transaction
    sendEmail(order); // Outside transaction

    updateOrderInTransaction(order); // Only DB update in transaction
}

@Transactional
private void updateOrderInTransaction(Order order) {
    orderRepository.save(order);
}

code_examples.bad:
private int counter = 0;

public void increment() {
    counter++; // Not thread-safe
}

code_examples.good:
private final AtomicInteger counter = new AtomicInteger(0);

public void increment() {
    counter.incrementAndGet(); // Thread-safe
}

code_examples.bad:
synchronized(lock1) {
    synchronized(lock2) {
        // Thread 1 holds lock1, waits for lock2
    }
}
// Meanwhile, Thread 2:
synchronized(lock2) {
    synchronized(lock1) {
        // Thread 2 holds lock2, waits for lock1
    }
}

code_examples.good:
// Always acquire locks in same order
synchronized(lock1) {
    synchronized(lock2) {
        // Both threads acquire in same order
    }
}

code_examples.bad:
// In reactive/async framework
public Mono<String> getData() {
    return Mono.fromCallable(() -> {
        Thread.sleep(1000); // Blocking on event loop thread
        return database.query();
    });
}

code_examples.good:
public Mono<String> getData() {
    return Mono.fromCallable(() -> database.query())
        .subscribeOn(Schedulers.boundedElastic()); // Use separate thread pool
}

code_examples.bad:
synchronized(this) {
    // Entire method synchronized
    validateData();
    processData();
    saveToDatabase();
    sendNotification();
}

code_examples.good:
validateData(); // No lock needed
processData(); // No lock needed

synchronized(this) {
    saveToDatabase(); // Only critical section locked
}

sendNotification(); // No lock needed

@Value("${api.url}")
private String apiUrl;

@Value("${api.timeout:5000}")
private int timeout;

@PostConstruct
public void validateConfiguration() {
    if (apiUrl == null || apiUrl.isEmpty()) {
        throw new IllegalStateException("api.url must be configured");
    }
    if (timeout <= 0) {
        throw new IllegalStateException("api.timeout must be positive");
    }
}

code_examples.bad:
public String callExternalApi() {
    return httpClient.get(url); // No retry on failure
}

code_examples.good:
@Retryable(
    value = {HttpTimeoutException.class, ConnectException.class},
    maxAttempts = 3,
    backoff = @Backoff(delay = 1000, multiplier = 2)
)
public String callExternalApi() {
    return httpClient.get(url);
}
